import Foundation
import XCTest
import SwiftUI
import UIKit
@testable import CoachApp

/// Run only with the private, disposable fixture generated by the isolated test runner.
@MainActor
final class RealConnectionTests: XCTestCase {
    func testConfirmedAnswerMatchesQuestionAcrossShufflesOnly() throws {
        let saved = ConfirmedAnswer(course: "course", week: 1, itemId: "item", server: "server", deviceId: "device", stem: "Question", options: ["A", "B"], choiceText: "B", status: "mastered", keyState: "VERIFIED")
        func item(_ stem: String = "Question", _ options: [String] = ["B", "A"], _ id: String = "item") -> PracticeItem {
            PracticeItem(id: id, stem: stem, options: options, layout: 2, status: "mastered")
        }
        func matches(_ item: PracticeItem, _ course: String = "course", _ week: Int = 1, _ server: String = "server", _ device: String = "device") -> Bool {
            saved.matches(item: item, course: course, week: week, server: server, deviceId: device)
        }
        XCTAssertTrue(matches(item()))
        XCTAssertFalse(matches(item("Changed")))
        XCTAssertFalse(matches(item("Question", ["B", "C"])))
        XCTAssertFalse(matches(item("Question", ["B", "B"])))
        XCTAssertFalse(matches(item("Question", ["B", "A"], "other")))
        XCTAssertFalse(matches(item(), "other"))
        XCTAssertFalse(matches(item(), "course", 2))
        XCTAssertFalse(matches(item(), "course", 1, "other"))
        XCTAssertFalse(matches(item(), "course", 1, "server", "other"))
        let oldRecord = #"{"course":"course","week":1,"itemId":"item","choice":0,"submissionId":"s","server":"server","deviceId":"device"}"#.data(using: .utf8)!
        let pending = try JSONDecoder().decode(PendingAnswer.self, from: oldRecord)
        XCTAssertNil(pending.itemStem)
        XCTAssertNil(pending.optionTexts)
    }

    private func fixture() throws -> [String: String] {
        let bundle = Bundle(for: Self.self)
        let url = try XCTUnwrap(bundle.url(forResource: "IsolatedFixture", withExtension: "plist"))
        return try XCTUnwrap(NSDictionary(contentsOf: url) as? [String: String])
    }

