    private func control(_ action: String, fixture: [String: String]) async throws {
        let base = try XCTUnwrap(fixture["control"])
        var request = URLRequest(url: try XCTUnwrap(URL(string: base + "/" + action)))
        request.httpMethod = "POST"
        request.setValue(try XCTUnwrap(fixture["controlSecret"]), forHTTPHeaderField: "X-Test-Control")
        let (_, response) = try await URLSession.shared.data(for: request)
        XCTAssertEqual((response as? HTTPURLResponse)?.statusCode, 204)
    }

    private func waitUntil(_ label: String, seconds: Int = 20, _ condition: () -> Bool) async throws {
        let start = ContinuousClock.now
        while !condition() && start.duration(to: .now) < .seconds(seconds) {
            try await Task.sleep(nanoseconds: 100_000_000)
        }
        XCTAssertTrue(condition(), "Timed out: \(label)")
        print("\(label) elapsed: \(start.duration(to: .now))")
    }

    private func answerEventCounts(_ connection: ConnectionModel, submission: String) async throws -> [String: Int] {
        let (address, credential) = try XCTUnwrap(connection.learningCredentials)
        var parts = URLComponents(url: address.url.appendingPathComponent("v1/courses/contract-course/events"), resolvingAgainstBaseURL: false)!
        parts.queryItems = [URLQueryItem(name: "after", value: "0"), URLQueryItem(name: "limit", value: "500")]
        var request = URLRequest(url: try XCTUnwrap(parts.url))
        request.setValue("Bearer \(credential.token)", forHTTPHeaderField: "Authorization")
        request.setValue(credential.deviceId, forHTTPHeaderField: "X-Coach-Device")
        let (data, response) = try await URLSession.shared.data(for: request)
        XCTAssertEqual((response as? HTTPURLResponse)?.statusCode, 200)
        let page = try XCTUnwrap(JSONSerialization.jsonObject(with: data) as? [String: Any])
        XCTAssertEqual(page["hasMore"] as? Bool, false, "Fixture must fit in one ledger page")
        let events = try XCTUnwrap(page["events"] as? [[String: Any]])
        var counts = [String: Int]()
        for event in events {
            guard let payload = event["payload"] as? [String: Any],
                  payload["attemptId"] as? String == "mainline-" + submission,
                  let type = event["type"] as? String else { continue }
            counts[type, default: 0] += 1
        }
        return counts
    }

    private func droppedReplies(_ values: [String: String]) async throws -> Int {
        var request = URLRequest(url: try XCTUnwrap(URL(string: try XCTUnwrap(values["control"]) + "/status")))
        request.setValue(try XCTUnwrap(values["controlSecret"]), forHTTPHeaderField: "X-Test-Control")
        let (data, response) = try await URLSession.shared.data(for: request)
        XCTAssertEqual((response as? HTTPURLResponse)?.statusCode, 200)
        return try XCTUnwrap((JSONSerialization.jsonObject(with: data) as? [String: Int])?["dropped"])
    }

    func testLostReplyCommit() async throws {
        let values = try fixture()
        let connection = ConnectionModel()
        await connection.pair(address: try XCTUnwrap(values["base"]), code: try XCTUnwrap(values["code"]))
        guard case .connected = connection.state else { XCTFail("Pair failed"); return }
        let learning = LearningModel(connection: connection)
        learning.course = "contract-course"
        await learning.loadCourse()
        await learning.openWeek(1)
        let item = try XCTUnwrap(learning.week?.items.first)
        let choice = try XCTUnwrap(item.options.firstIndex(of: "Pears"))
        try await control("arm-loss", fixture: values)
        await learning.submit(item: item, choice: choice)
        let pending = try XCTUnwrap(learning.pending, "A lost reply must remain pending")
        XCTAssertNil(learning.receipt)
        XCTAssertNotNil(learning.message)
        let dropped = try await droppedReplies(values)
        XCTAssertGreaterThan(dropped, 0, "No successful server reply was actually dropped")
        let counts = try await answerEventCounts(connection, submission: pending.submissionId)
        for type in ["question_posed", "answer_submitted", "attempt_graded"] { XCTAssertEqual(counts[type], 1, type) }
        print("Lost reply: \(dropped) successful response(s) withheld; Ledger counts before retry: \(counts)")
    }

    func testLostReplyRestore() async throws {
        let values = try fixture()
        let connection = ConnectionModel()
        await connection.restore()
        guard case .connected = connection.state else { XCTFail("Restore failed"); return }
        let learning = LearningModel(connection: connection)
        let pending = try XCTUnwrap(learning.pending)
        let before = try await answerEventCounts(connection, submission: pending.submissionId)
        try await control("disarm-loss", fixture: values)
        await learning.retryPending()
        XCTAssertNil(learning.pending)
        XCTAssertEqual(learning.receipt?.attemptId, "mainline-" + pending.submissionId)
        XCTAssertEqual(learning.receipt?.status, "mastered")
        let after = try await answerEventCounts(connection, submission: pending.submissionId)
        XCTAssertEqual(before, after)
        for type in ["question_posed", "answer_submitted", "attempt_graded"] { XCTAssertEqual(after[type], 1, type) }
        await learning.loadCourse()
        await learning.openWeek(1)
        XCTAssertEqual(learning.week?.items.first?.status, "mastered")
        print("Ledger counts after retry: \(after)")
    }

    func testRealtimeOfflineAndRetry() async throws {
        let values = try fixture()
        let connection = ConnectionModel()
        await connection.pair(address: try XCTUnwrap(values["base"]), code: try XCTUnwrap(values["code"]))
        guard case .connected = connection.state else { XCTFail("Pair failed"); return }
        try await waitUntil("WS initial hello") { connection.realtime == .online }
        let learning = LearningModel(connection: connection)
        learning.course = "contract-course"
        await learning.loadCourse()
        await learning.openWeek(1)
        let item = try XCTUnwrap(learning.week?.items.first)
        let choice = try XCTUnwrap(item.options.firstIndex(of: "Pears"))
        try await control("down", fixture: values)
        try await waitUntil("WS disconnected") { connection.realtime == .offline }
        await learning.submit(item: item, choice: choice)
        let pending = try XCTUnwrap(learning.pending)
        XCTAssertNil(learning.receipt)
        XCTAssertNotNil(learning.message)
        try await control("up", fixture: values)
        try await waitUntil("WS reconnected") { connection.realtime == .online }
        await learning.retryPending()
        XCTAssertNil(learning.pending)
        XCTAssertEqual(learning.receipt?.attemptId, "mainline-" + pending.submissionId)
        XCTAssertEqual(learning.receipt?.status, "mastered")
        await learning.loadCourse()
        await learning.openWeek(1)
        XCTAssertEqual(learning.week?.items.first?.status, "mastered")
    }

    func testRealtimeRestoreAndRevoke() async throws {
        let values = try fixture()
        let store = CredentialStore(service: "coach.ton1411.device")
        defer { try? store.delete() }
        let (address, credential) = try XCTUnwrap(store.load())
        let connection = ConnectionModel()
        await connection.restore()
        guard case .connected = connection.state else { XCTFail("Keychain restore failed"); return }
        try await waitUntil("restored WS hello") { connection.realtime == .online }
        var parts = URLComponents(url: address.url.appendingPathComponent("v1/ws"), resolvingAgainstBaseURL: false)!
        parts.scheme = "ws"
        var request = URLRequest(url: try XCTUnwrap(parts.url))
        request.setValue("Bearer \(credential.token)", forHTTPHeaderField: "Authorization")
        request.setValue(credential.deviceId, forHTTPHeaderField: "X-Coach-Device")
        let probe = URLSession.shared.webSocketTask(with: request)
        probe.resume()
        _ = try await probe.receive() // Server's authenticated hello.
        let hint = try await probe.receive() // Initial ledger hint may already be queued.
        guard case .string(let text) = hint, text.contains("\"ledger\"") else {
            XCTFail("Expected the initial ledger hint"); return
        }
        var revoke = URLRequest(url: address.url.appendingPathComponent("v1/devices/\(credential.deviceId)"))
        revoke.httpMethod = "DELETE"
        revoke.setValue("Bearer \(try XCTUnwrap(values["adminToken"]))", forHTTPHeaderField: "Authorization")
        revoke.setValue("desktop", forHTTPHeaderField: "X-Coach-Device")
        let (_, response) = try await URLSession.shared.data(for: revoke)
        XCTAssertEqual((response as? HTTPURLResponse)?.statusCode, 204)
        do { _ = try await probe.receive(); XCTFail("Revoked socket unexpectedly received a frame") }
        catch { XCTAssertEqual(probe.closeCode, .policyViolation) }
        try await waitUntil("revoked active WS") { connection.state == .revoked }
        do { _ = try await PairingClient(address: address).hello(credential: credential); XCTFail("Revoked HTTP accepted") }
        catch ConnectionError.unauthorized { print("Revoked HTTP: 401") }
        let rejected = URLSession.shared.webSocketTask(with: request)
        rejected.resume()
        do { _ = try await rejected.receive(); XCTFail("Revoked WS accepted") }
        catch {
            XCTAssertEqual((rejected.response as? HTTPURLResponse)?.statusCode, 401)
            print("Revoked WS handshake: 401; open socket close: 1008")
        }
        rejected.cancel(with: .goingAway, reason: nil)
    }

    func testLedgerOfflineCatchUp() async throws {
        let values = try fixture()
        let connection = ConnectionModel(ledgerPageSize: 1)
        await connection.pair(address: try XCTUnwrap(values["base"]), code: try XCTUnwrap(values["code"]))
        guard case .connected = connection.state else { XCTFail("Pair failed"); return }
        try await waitUntil("WS initial hello") { connection.realtime == .online }
        let learning = LearningModel(connection: connection)
        learning.course = "contract-course"
        await learning.loadCourse(); await learning.openWeek(1)
        let item = try XCTUnwrap(learning.week?.items.first)
        XCTAssertNotEqual(item.status, "mastered")
        let scene = try XCTUnwrap(UIApplication.shared.connectedScenes.compactMap { $0 as? UIWindowScene }.first)
        let window = UIWindow(windowScene: scene)
        window.frame = scene.coordinateSpace.bounds
        window.rootViewController = UIHostingController(rootView: ScrollView { LearningView(connection: connection, model: learning).padding() })
        window.makeKeyAndVisible()
        defer { window.isHidden = true }
        let choice = try XCTUnwrap(item.options.firstIndex(of: "Pears"))
        try await control("down", fixture: values)
        try await waitUntil("WS disconnected") { connection.realtime == .offline }
        var request = URLRequest(url: try XCTUnwrap(URL(string: try XCTUnwrap(values["control"]) + "/submit")))
        request.httpMethod = "POST"
        request.setValue(try XCTUnwrap(values["controlSecret"]), forHTTPHeaderField: "X-Test-Control")
        request.httpBody = try JSONSerialization.data(withJSONObject: ["itemId": item.id, "choice": choice, "layout": try XCTUnwrap(item.layout), "submissionId": "ledger-catchup-test"])
        let (_, submitted) = try await URLSession.shared.data(for: request)
        XCTAssertEqual((submitted as? HTTPURLResponse)?.statusCode, 204)
        try await control("up", fixture: values)
        try await waitUntil("ledger pages caught up") { (connection.ledgerReplica?.courses["contract-course"]?.events.count ?? 0) >= 3 }
        try await waitUntil("learning view model auto-refresh") { learning.week?.items.first?.status == "mastered" && !learning.busy }
        XCTAssertNil(learning.pending)
        window.layoutIfNeeded()
        try await Task.sleep(nanoseconds: 500_000_000)
        let renderer = UIGraphicsImageRenderer(bounds: window.bounds)
        let screenshot = renderer.image { _ in window.drawHierarchy(in: window.bounds, afterScreenUpdates: true) }
        let screenshotURL = FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0].appendingPathComponent("ledger-ui.png")
        try XCTUnwrap(screenshot.pngData()).write(to: screenshotURL)
        let original = try XCTUnwrap(connection.ledgerReplica?.courses["contract-course"])
        XCTAssertEqual(original.events.count, 3)
        XCTAssertEqual(Set(original.events.map(\.id)).count, 3)
        XCTAssertEqual(connection.ledgerVersions["contract-course"], 3, "Each real HTTP page has one event")
        let (_, duplicateResponse) = try await URLSession.shared.data(for: request)
        XCTAssertEqual((duplicateResponse as? HTTPURLResponse)?.statusCode, 204)
        let counts = try await answerEventCounts(connection, submission: "ledger-catchup-test")
        for type in ["question_posed", "answer_submitted", "attempt_graded"] { XCTAssertEqual(counts[type], 1, type) }
        print("Ledger counts after identical retry: \(counts)")
        let (address, credential) = try XCTUnwrap(connection.learningCredentials)
        var components = URLComponents(url: address.url.appendingPathComponent("v1/courses/contract-course/events"), resolvingAgainstBaseURL: false)!
        components.queryItems = [URLQueryItem(name: "after", value: "0"), URLQueryItem(name: "limit", value: "500")]
        var replay = URLRequest(url: try XCTUnwrap(components.url))
        replay.setValue("Bearer \(credential.token)", forHTTPHeaderField: "Authorization")
        replay.setValue(credential.deviceId, forHTTPHeaderField: "X-Coach-Device")
        let (page, response) = try await URLSession.shared.data(for: replay)
        XCTAssertEqual((response as? HTTPURLResponse)?.statusCode, 200)
        var replica = try XCTUnwrap(connection.ledgerReplica)
        let file = try LedgerReplica.file(address: address, credential: credential)
        let result = try replica.apply(data: page, course: "contract-course", file: file)
        XCTAssertFalse(result.1, "Overlapping replay must not add events")
        XCTAssertEqual(replica.courses["contract-course"]?.events.count, 3)
        XCTAssertEqual(replica.courses["contract-course"]?.cursor, original.cursor)
        // Stop after page one and reload the same atomic file before requesting page two.
        let boundaryFile = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
        defer { try? FileManager.default.removeItem(at: boundaryFile) }
        var boundary = LedgerReplica(epoch: replica.epoch)
        var after: Int64 = 0
        var pageCount = 0
        repeat {
            components.queryItems = [URLQueryItem(name: "after", value: String(after)), URLQueryItem(name: "limit", value: "1")]
            replay.url = try XCTUnwrap(components.url)
            let (data, pageResponse) = try await URLSession.shared.data(for: replay)
            XCTAssertEqual((pageResponse as? HTTPURLResponse)?.statusCode, 200)
            let pageResult = try boundary.apply(data: data, course: "contract-course", file: boundaryFile)
            pageCount += 1
            if pageCount == 1 { boundary = try LedgerReplica.load(file: boundaryFile, epoch: replica.epoch) }
            after = try XCTUnwrap(boundary.courses["contract-course"]?.cursor)
            if !pageResult.0 { break }
        } while pageCount < 10
        XCTAssertEqual(pageCount, 3)
        XCTAssertEqual(boundary.courses["contract-course"]?.events.map(\.id), original.events.map(\.id))
        XCTAssertEqual(after, original.cursor)
        // Exercise the cache limit and replay across an actual persisted boundary.
        let cacheFile = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
        defer { try? FileManager.default.removeItem(at: cacheFile) }
        var cache = LedgerReplica(epoch: "cache-test")
        let rows: [[String: Any]] = (1...300).map { ["seq": $0, "id": "event-\($0)", "courseId": "a", "payload": ["value": $0]] }
        func cachePage(_ events: [[String: Any]], _ through: Int) throws -> Data {
            try JSONSerialization.data(withJSONObject: ["epoch": "cache-test", "throughSeq": through, "hasMore": false, "events": events])
        }
        _ = try cache.apply(data: cachePage(rows, 300), course: "a", file: cacheFile)
        XCTAssertEqual(cache.courses["a"]?.events.count, LedgerReplica.maxCachedEvents)
        cache = try LedgerReplica.load(file: cacheFile, epoch: "cache-test")
        XCTAssertEqual(cache.courses["a"]?.cursor, 300)
        XCTAssertFalse(try cache.apply(data: cachePage([rows[0], rows[299]], 300), course: "a", file: cacheFile).1)
        let large: [[String: Any]] = [["seq": 301, "id": "large", "courseId": "a", "payload": String(repeating: "x", count: LedgerReplica.maxCachedBytes + 1)]]
        XCTAssertTrue(try cache.apply(data: cachePage(large, 301), course: "a", file: cacheFile).1)
        XCTAssertLessThanOrEqual(cache.courses.values.flatMap(\.events).reduce(0) { $0 + $1.json.count }, LedgerReplica.maxCachedBytes)
        XCTAssertEqual(try LedgerReplica.load(file: cacheFile, epoch: "cache-test").courses["a"]?.cursor, 301)
        print("Ledger catchup: 3 actual HTTP pages, 3 unique events; overlapping replay adds 0; page-boundary restore cursor \(original.cursor); cache 256 and byte cap verified; hosted learning status mastered")
    }

    func testLedgerRestore() async throws {
        let connection = ConnectionModel(ledgerPageSize: 1)
        await connection.restore()
        guard case .connected = connection.state else { XCTFail("Restore failed"); return }
        try await waitUntil("restored ledger cursor") { (connection.ledgerReplica?.courses["contract-course"]?.events.count ?? 0) == 3 }
        let course = try XCTUnwrap(connection.ledgerReplica?.courses["contract-course"])
        XCTAssertEqual(Set(course.events.map(\.id)).count, 3)
        XCTAssertGreaterThan(course.cursor, 0)
        // A fresh socket receives the server's overlapping initial notification.
        connection.startRealtime()
        try await waitUntil("overlapping reconnect") { connection.realtime == .online }
        try await Task.sleep(nanoseconds: 1_000_000_000)
        XCTAssertEqual(connection.ledgerReplica?.courses["contract-course"]?.events.count, 3)
        XCTAssertEqual(connection.ledgerReplica?.courses["contract-course"]?.cursor, course.cursor)
        print("Ledger restore: cursor \(course.cursor), 3 unique events after reconnect")
        let (address, credential) = try XCTUnwrap(connection.learningCredentials)
        let file = try LedgerReplica.file(address: address, credential: credential)
        XCTAssertTrue(FileManager.default.fileExists(atPath: file.path))
        connection.forget()
        XCTAssertFalse(FileManager.default.fileExists(atPath: file.path))
        XCTAssertNil(try CredentialStore(service: "coach.ton1411.device").load())
    }

}
